mapper.update:
UPDATE comments SET DELETED_AT = CURRENT_TIMESTAMP, UPDATED_AT = CURRENT_TIMESTAMP, DELETED_BY_TYPE = 'SELF'
WHERE COMMENT_ID = #{commentId} AND POST_ID = #{postId}
    AND USER_ID = #{userId} AND DELETED_AT IS NULL

UPDATE comments SET CONTENT = #{content}, UPDATED_AT = CURRENT_TIMESTAMP
WHERE COMMENT_ID = #{commentId} AND POST_ID = #{postId}
    AND USER_ID = #{userId} AND DELETED_AT IS NULL
